const projectRoot = resolve(import.meta.dirname, '..');
const CONFIG_TEST_PLATFORM = process.platform === 'win32' ? 'win32' : 'linux';

function runFixture(t, scenario) {
  const root = mkdtempSync(join(tmpdir(), `vibe-usage-quote0-setup-fixture-${scenario}-`));
  t.after(() => rmSync(root, { recursive: true, force: true }));
  const result = spawnSync(process.execPath, ['src/index.js', 'enable'], {
    cwd: projectRoot,
    env: {
      ...process.env,
      NODE_ENV: 'test',
      VIBE_USAGE_QUOTE0_SETUP_FIXTURE: scenario,
      VIBE_USAGE_QUOTE0_SETUP_FIXTURE_ROOT: root,
    },
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  return {
    ...result,
    root,
    vibePath: join(root, 'home', '.vibe-usage', 'config.json'),
    quotePath: join(root, 'appdata', 'vibe-usage-quote0', 'config.json'),
  };
}

test('CLI help 列出 enable、disable、update、interval 与 display 命令', async () => {
  const output = [];
  await runCli(['--help'], { stdout: (line) => output.push(line) });
  const help = output.join('\n');
  assert.match(help, /vibe-usage-quote0 enable/);
  assert.match(help, /vibe-usage-quote0 disable/);
  assert.match(help, /vibe-usage-quote0 update/);
  assert.match(help, /vibe-usage-quote0 interval <minutes>/);
  assert.match(help, /vibe-usage-quote0 display <main\|secondary>/);
  assert.match(help, /today\|24h\|Nd\|yyyyMMdd-yyyyMMdd/);
  assert.match(help, /当前平台定时刷新/);
  assert.doesNotMatch(help, /安装 Windows 定时刷新/);
  assert.doesNotMatch(help, /vibe-usage-quote0 setup/);
});

test('CLI display 独立保存主要与次要显示档位且不要求凭据', async (t) => {
  const root = mkdtempSync(join(tmpdir(), 'vibe-usage-quote0-display-'));
  t.after(() => rmSync(root, { recursive: true, force: true }));
  const output = [];
  const tracker = createChmodTracker();
  const options = {
    env: { XDG_CONFIG_HOME: root },
    platform: CONFIG_TEST_PLATFORM,
    fileSystem: tracker.fileSystem,
    protectFile() {},
    stdout: (line) => output.push(line),
  };

  const main = await runCli(['display', 'main', '24H'], options);
  const secondary = await runCli(['display', 'secondary', '20260701-20260731'], options);
  const path = join(root, 'vibe-usage-quote0', 'config.json');

  assert.equal(main.range.value, '24h');
  assert.equal(secondary.range.value, '20260701-20260731');
  assert.deepEqual(JSON.parse(readFileSync(path, 'utf8')), {
    display: { main: '24h', secondary: '20260701-20260731' },
  });
  if (process.platform !== 'win32') assert.equal(hasPrivateChmod(tracker.calls, path), true);
  assert.match(output.join('\n'), /主要数据.*滚动 24 小时/);
  assert.match(output.join('\n'), /次要数据.*2026-07-01 至 2026-07-31/);
});

test('CLI display 拒绝缺失、多余、未知区域与非法档位', async () => {
  const cases = [
    ['display'],
    ['display', 'main'],
    ['display', 'main', '7d', 'extra'],
    ['display', 'primary', '7d'],
    ['display', 'main', '0d'],
    ['display', 'secondary', '20260230-20260301'],
  ];
  for (const argv of cases) {
    await assert.rejects(runCli(argv, { env: {}, platform: 'linux' }), /用法|显示区域|显示档位|日期无效/);
  }
});

test('CLI interval 无需凭据即可安全保存并等待 Linux enable 安装调度任务', async (t) => {
  const root = mkdtempSync(join(tmpdir(), 'vibe-usage-quote0-interval-'));
  t.after(() => rmSync(root, { recursive: true, force: true }));
  const output = [];
  const tracker = createChmodTracker();
  const result = await runCli(['interval', '45'], {
    env: { XDG_CONFIG_HOME: root },
    platform: 'linux',
    fileSystem: tracker.fileSystem,
    stdout: (line) => output.push(line),
  });
  const path = join(root, 'vibe-usage-quote0', 'config.json');

  assert.equal(result.intervalMinutes, 45);
  assert.deepEqual(JSON.parse(readFileSync(path, 'utf8')), { intervalMinutes: 45 });
  assert.equal(hasPrivateChmod(tracker.calls, path), true);
  if (process.platform !== 'win32') assert.equal(statSync(path).mode & 0o777, 0o600);
  assert.match(output.join('\n'), /45 分钟/);
  assert.match(output.join('\n'), /未检测到已安装调度任务/);
});

test('CLI interval 拒绝缺失、多余与非法分钟参数', async () => {
  for (const argv of [['interval'], ['interval', '30', 'extra'], ['interval', '0'], ['interval', '1.5']]) {
    await assert.rejects(runCli(argv, { env: {}, platform: 'linux' }), /用法|整数分钟/);
  }
});

test('CLI enable 只负责编排并拒绝命令行秘密参数', async () => {
  let calls = 0;
  await assert.rejects(
    runCli(['enable', 'secret-on-argv'], { enableRunner: async () => { calls += 1; } }),
    /不接受命令行参数/,
  );
  assert.equal(calls, 0);

  const result = await runCli(['enable'], {
    env: {},
    enableOptions: { io: { isTTY: true } },
    enableRunner: async (options) => {
      calls += 1;
      assert.equal(options.io.isTTY, true);
      return { configured: true };
    },
  });
  assert.deepEqual(result, { configured: true });
  assert.equal(calls, 1);
});

test('CLI 不再兼容 setup 旧命令', async () => {
  await assert.rejects(runCli(['setup']), /未知命令：setup/);
});

test('CLI disable 与 update 拒绝参数并调用各自执行器', async () => {
  await assert.rejects(runCli(['disable', 'extra']), /用法/);
  await assert.rejects(runCli(['update', 'extra']), /用法/);

  const output = [];
  const disabled = await runCli(['disable'], {
    stdout: (line) => output.push(line),
    disableRunner: async () => ({ platform: 'darwin', disabled: true }),
  });
  const updated = await runCli(['update'], {
    stdout: (line) => output.push(line),
    updateRunner: async () => ({ packageSpec: 'vibe-usage-quote0@latest' }),
  });

  assert.equal(disabled.command, 'disable');
  assert.equal(updated.command, 'update');
  assert.match(output.join('\n'), /已解除本工具的定时刷新任务/);
  assert.match(output.join('\n'), /已更新至 npm 最新版/);
});

test('CLI enable 打包测试入口完成安全配置、push 与安装阶段', (t) => {
  const result = runFixture(t, 'success');
  assert.equal(result.status, 0, result.stderr);
  assert.equal(existsSync(result.vibePath), true);
  assert.equal(existsSync(result.quotePath), true);
  assert.match(result.stdout, /真实 push 已确认渲染变化/);
  assert.match(result.stdout, /enable_fixture_completed=true/);
  assert.doesNotMatch(
    `${result.stdout}\n${result.stderr}`,
    /fixture-(?:vibe|quote|device)-placeholder/,
  );
});

test('CLI enable 的 401 fixture 非零退出、无配置变化、无秘密输出', (t) => {
  const result = runFixture(t, '401');
  assert.equal(result.status, 1);
  assert.equal(existsSync(result.vibePath), false);
  assert.equal(existsSync(result.quotePath), false);
  assert.match(result.stderr, /阶段 凭据验证 失败.*HTTP 401/);
  assert.doesNotMatch(
    `${result.stdout}\n${result.stderr}`,
    /fixture-(?:vibe|quote|device)-placeholder/,
  );
});
name: CI

on:
  push:
  pull_request:
  workflow_dispatch:

permissions:
  contents: read

jobs:
  test:
    strategy:
      fail-fast: false
      matrix:
        os:
          - windows-latest
          - macos-latest
          - ubuntu-latest
    runs-on: ${{ matrix.os }}
    steps:
      - uses: actions/checkout@v7
      - uses: pnpm/action-setup@v6
      - uses: actions/setup-node@v7
        with:
          node-version: 20
          cache: pnpm
      - run: pnpm install --frozen-lockfile
      - run: pnpm build
      - run: pnpm test
      - run: pnpm security-check
      - run: pnpm pack --dry-run
      - name: Lint launchd template
        if: runner.os == 'macOS'
        run: plutil -lint launchd/com.vibeusage.vibe-usage-quote0.plist
      - name: Validate Windows package and scheduled failure path
        if: runner.os == 'Windows'
        shell: powershell
        run: |
          if ($PSVersionTable.PSVersion.Major -ne 5 -or $PSVersionTable.PSVersion.Minor -lt 1) {
            throw "Expected Windows PowerShell 5.1, got $($PSVersionTable.PSVersion)"
          }

          $parseErrors = @()
          foreach ($scriptFile in Get-ChildItem -LiteralPath windows -Filter '*.ps1') {
            $tokens = $null
            $errors = $null
            [Management.Automation.Language.Parser]::ParseFile(
              $scriptFile.FullName,
              [ref]$tokens,
              [ref]$errors
            ) | Out-Null
            $parseErrors += $errors
          }
          if ($parseErrors.Count -gt 0) {
            throw ($parseErrors | ForEach-Object Message | Out-String)
          }

          pnpm pack --pack-destination $env:RUNNER_TEMP
          if ($LASTEXITCODE -ne 0) { throw 'pnpm pack failed' }
          $tarball = Get-ChildItem -LiteralPath $env:RUNNER_TEMP -Filter 'vibe-usage-quote0-*.tgz' |
            Sort-Object LastWriteTime -Descending |
            Select-Object -First 1
          npm install --global $tarball.FullName
          if ($LASTEXITCODE -ne 0) { throw 'global tarball install failed' }

          $nodePath = (Get-Command node.exe -CommandType Application | Select-Object -First 1).Source
          $cliPath = (Get-Command vibe-usage-quote0.cmd -CommandType Application | Select-Object -First 1).Source
          & $cliPath --help
          if ($LASTEXITCODE -ne 0) { throw '.cmd --help failed' }
          $helpOutput = & $cliPath --help | Out-String
          if ($LASTEXITCODE -ne 0 -or $helpOutput -notmatch 'vibe-usage-quote0 enable' -or $helpOutput -match 'vibe-usage-quote0 setup') {
            throw '.cmd help does not expose only the new enable command'
          }

          $fixtureStdout = Join-Path $env:RUNNER_TEMP 'setup-fixture.stdout.txt'
          $fixtureStderr = Join-Path $env:RUNNER_TEMP 'setup-fixture.stderr.txt'
          $env:NODE_ENV = 'test'
          try {
            $failureRoot = Join-Path $env:RUNNER_TEMP 'vibe-usage-quote0-setup-fixture-401'
            $env:VIBE_USAGE_QUOTE0_SETUP_FIXTURE = '401'
            $env:VIBE_USAGE_QUOTE0_SETUP_FIXTURE_ROOT = $failureRoot
            $failureProcess = Start-Process `
              -FilePath $cliPath `
              -ArgumentList 'enable' `
              -RedirectStandardOutput $fixtureStdout `
              -RedirectStandardError $fixtureStderr `
              -Wait `
              -PassThru `
              -NoNewWindow
            if ($failureProcess.ExitCode -ne 1) {
              throw "enable 401 fixture returned $($failureProcess.ExitCode), expected 1"
            }
            $failureConfigs = @(Get-ChildItem -LiteralPath $failureRoot -Filter 'config.json' -Recurse -ErrorAction SilentlyContinue)
            if ($failureConfigs.Count -ne 0) { throw 'enable 401 fixture changed config' }
            $failureOutput = (Get-Content -LiteralPath $fixtureStdout -Raw) + (Get-Content -LiteralPath $fixtureStderr -Raw)
            if ($failureOutput -match 'fixture-(vibe|quote|device)-placeholder') {
              throw 'enable 401 fixture leaked credential placeholders'
            }

            $successRoot = Join-Path $env:RUNNER_TEMP 'vibe-usage-quote0-setup-fixture-success'
            $env:VIBE_USAGE_QUOTE0_SETUP_FIXTURE = 'success'
            $env:VIBE_USAGE_QUOTE0_SETUP_FIXTURE_ROOT = $successRoot
            $successProcess = Start-Process `
              -FilePath $cliPath `
              -ArgumentList 'enable' `
              -RedirectStandardOutput $fixtureStdout `
              -RedirectStandardError $fixtureStderr `
              -Wait `
              -PassThru `
              -NoNewWindow
            if ($successProcess.ExitCode -ne 0) {
              throw "enable success fixture returned $($successProcess.ExitCode)"
            }
            $successConfigs = @(Get-ChildItem -LiteralPath $successRoot -Filter 'config.json' -Recurse)
            if ($successConfigs.Count -ne 2) { throw 'enable success fixture did not write two configs' }
            $successOutput = (Get-Content -LiteralPath $fixtureStdout -Raw) + (Get-Content -LiteralPath $fixtureStderr -Raw)
            if ($successOutput -notmatch 'enable_fixture_completed=true') {
              throw 'enable success fixture did not reach completion'
            }
            if ($successOutput -match 'fixture-(vibe|quote|device)-placeholder') {
              throw 'enable success fixture leaked credential placeholders'
            }
          } finally {
            Remove-Item Env:\VIBE_USAGE_QUOTE0_SETUP_FIXTURE -ErrorAction SilentlyContinue
            Remove-Item Env:\VIBE_USAGE_QUOTE0_SETUP_FIXTURE_ROOT -ErrorAction SilentlyContinue
            Remove-Item Env:\NODE_ENV -ErrorAction SilentlyContinue
          }

          $packageRoot = Join-Path ((npm root -g).Trim()) 'vibe-usage-quote0'
          $taskName = 'VibeUsageQuote0'
          $vibeConfigDir = Join-Path $env:USERPROFILE '.vibe-usage'
          $vibeConfigPath = Join-Path $vibeConfigDir 'config.json'
          $configDir = Join-Path $env:APPDATA 'vibe-usage-quote0'
          $configPath = Join-Path $configDir 'config.json'
          $logPath = Join-Path $env:RUNNER_TEMP 'scheduled-task.log'
          $scheduledLogPath = Join-Path $env:LOCALAPPDATA 'vibe-usage-quote0\logs\scheduled-task.log'
          $shimBackup = Join-Path $env:RUNNER_TEMP 'vibe-usage-quote0.cmd.backup'
          $installScript = Join-Path $packageRoot 'windows\install.ps1'
          $setupAclScript = Join-Path $packageRoot 'windows\setup.ps1'
          $intervalScript = Join-Path $packageRoot 'windows\update-interval.ps1'
          $runScript = Join-Path $packageRoot 'windows\run.ps1'
          $uninstallScript = Join-Path $packageRoot 'windows\uninstall.ps1'
          $powerShell = Join-Path $PSHOME 'powershell.exe'
          $placeholder = 'scheduler-ci-secret-placeholder'

          try {
            Copy-Item -LiteralPath $cliPath -Destination $shimBackup
            Set-Content -LiteralPath $cliPath -Encoding Ascii -Value @(
              '@echo off',
              'if "%~1"=="doctor" exit /b 0',
              'if "%~1"=="push" echo scheduler-ci-secret-placeholder',
              'if "%~1"=="push" exit /b 1',
              'exit /b 2'
            )

            New-Item -ItemType Directory -Path $vibeConfigDir -Force | Out-Null
            New-Item -ItemType Directory -Path $configDir -Force | Out-Null
            Set-Content -LiteralPath $vibeConfigPath -Encoding Ascii -Value '{"apiKey":"ci-vibe-placeholder"}'
            Set-Content -LiteralPath $configPath -Encoding Ascii -Value '{"apiKey":"ci-placeholder","deviceId":"ci-device"}'
            foreach ($privateConfigPath in @($vibeConfigPath, $configPath)) {
              & $powerShell -NoProfile -ExecutionPolicy Bypass -File $setupAclScript -Path $privateConfigPath
              if ($LASTEXITCODE -ne 0) { throw 'private config ACL setup failed' }
            }

            & $powerShell -NoProfile -ExecutionPolicy Bypass -File $installScript -DryRun -NodePath $nodePath -CliPath $cliPath -ConfigPath $configPath
            if ($LASTEXITCODE -ne 0) { throw 'installer dry-run failed' }
            if ($null -ne (Get-ScheduledTask -TaskName $taskName -ErrorAction SilentlyContinue)) {
              throw 'installer dry-run changed Task Scheduler'
            }

            $runArguments = '-NoProfile -ExecutionPolicy Bypass -File "{0}" -NodePath "{1}" -CliPath "{2}" -Command push -LogPath "{3}"' -f $runScript, $nodePath, $cliPath, $logPath
            $runProcess = Start-Process -FilePath $powerShell -ArgumentList $runArguments -Wait -PassThru -NoNewWindow
